<label class="field full">Link when clicked (optional)<input id="sd-link" value="${esc(b.link||'')}" placeholder="product-details.html?id=5  or  shop.html?cat=mobiles"></label>${k==='slider'?`<div class="field full"><label class="a-chk"><input id="sd-bon" type="checkbox" ${b.btn_on!==false?'checked':''}> Show “Shop Now” button on this banner</label></div><label class="field">Button text (English)<input id="sd-btxt" value="${esc(b.btn_text||'')}" placeholder="Shop now"></label><label class="field">Button text (Urdu)<input id="sd-btxtur" dir="rtl" value="${esc(b.btn_text_ur||'')}"></label><label class="field full">Button link (empty = banner link, or the Shop page)<input id="sd-blink" value="${esc(b.btn_link||'')}" placeholder="shop.html"></label>`:''}</div>
